import{c as e,Q as a,j as s,m as d}from"./chunks/framework.CWBTDBPu.js";const h=JSON.parse('{"title":"YuRandomTeleport 权限节点","description":"","frontmatter":{"title":"YuRandomTeleport 权限节点"},"headers":[],"relativePath":"plugins/items/yu-random-teleport/permissions.md","filePath":"plugins/items/yu-random-teleport/permissions.md"}'),o={name:"plugins/items/yu-random-teleport/permissions.md"};function p(n,t,r,c,l,i){return a(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="yurandomteleport-权限节点" tabindex="-1">YuRandomTeleport 权限节点 <a class="header-anchor" href="#yurandomteleport-权限节点" aria-label="Permalink to &quot;YuRandomTeleport 权限节点&quot;">​</a></h1><h2 id="权限总览" tabindex="-1">权限总览 <a class="header-anchor" href="#权限总览" aria-label="Permalink to &quot;权限总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>yurtp.use</code></td><td><code>true</code></td><td>允许使用随机传送。目标玩家执行或被管理员代传送时都需要该权限。</td></tr><tr><td><code>yurtp.reload</code></td><td><code>op</code></td><td>允许执行 <code>/yurtp reload</code>。</td></tr><tr><td><code>yurtp.teleport.others</code></td><td><code>op</code></td><td>允许将其他在线玩家随机传送。</td></tr><tr><td><code>yurtp.bypass.cooldown</code></td><td><code>op</code></td><td>允许玩家绕过自己的冷却。</td></tr><tr><td><code>yurtp.bypass.cooldown.others</code></td><td><code>op</code></td><td>插件声明了该权限，用于表示代传送时绕过目标冷却的管理意图。当前命令实现主要检查目标玩家的 <code>yurtp.bypass.cooldown</code>。</td></tr><tr><td><code>yurtp.bypass.cost</code></td><td><code>op</code></td><td>允许命令执行者绕过 Vault 扣费。</td></tr><tr><td><code>yurtp.bypass.wait</code></td><td><code>op</code></td><td>允许目标玩家跳过传送等待时间。</td></tr></tbody></table><h2 id="普通玩家组" tabindex="-1">普通玩家组 <a class="header-anchor" href="#普通玩家组" aria-label="Permalink to &quot;普通玩家组&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yurtp.use</span></span></code></pre></div><p>适合大多数服务器的普通玩家。若服务器有登录大厅、主城或副本世界，应通过 <code>world-blacklist</code> 或 <code>world-whitelist</code> 控制可用世界，而不是只依赖权限。</p><h2 id="vip-或赞助组" tabindex="-1">VIP 或赞助组 <a class="header-anchor" href="#vip-或赞助组" aria-label="Permalink to &quot;VIP 或赞助组&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yurtp.use</span></span>
<span class="line"><span>yurtp.bypass.cooldown</span></span></code></pre></div><p>如果希望 VIP 仍然付费，但不受冷却限制，只给予 <code>yurtp.bypass.cooldown</code>。如果希望 VIP 免等待，可额外给予：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yurtp.bypass.wait</span></span></code></pre></div><p>如果希望 VIP 免扣费，可额外给予：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yurtp.bypass.cost</span></span></code></pre></div><h2 id="管理员组" tabindex="-1">管理员组 <a class="header-anchor" href="#管理员组" aria-label="Permalink to &quot;管理员组&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yurtp.use</span></span>
<span class="line"><span>yurtp.reload</span></span>
<span class="line"><span>yurtp.teleport.others</span></span>
<span class="line"><span>yurtp.bypass.cooldown</span></span>
<span class="line"><span>yurtp.bypass.cost</span></span>
<span class="line"><span>yurtp.bypass.wait</span></span></code></pre></div><p>管理员组可以重载配置、代传送玩家，并可按需要绕过费用、冷却和等待。</p><h2 id="控制台与命令方块" tabindex="-1">控制台与命令方块 <a class="header-anchor" href="#控制台与命令方块" aria-label="Permalink to &quot;控制台与命令方块&quot;">​</a></h2><p>控制台没有玩家位置，因此不能直接执行无参数 <code>/yurtp</code>。控制台应使用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yurtp &lt;玩家&gt;</span></span>
<span class="line"><span>yurtp &lt;玩家&gt; &lt;世界&gt;</span></span>
<span class="line"><span>yurtp reload</span></span></code></pre></div><p>控制台权限由服务端命令系统处理，通常不需要额外配置权限插件。</p><h2 id="权限设计建议" tabindex="-1">权限设计建议 <a class="header-anchor" href="#权限设计建议" aria-label="Permalink to &quot;权限设计建议&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目标</th><th>建议</th></tr></thead><tbody><tr><td>防止战斗逃跑</td><td>不给普通玩家 <code>yurtp.bypass.wait</code>，并保持 <code>teleport.cancel-on-move: true</code>。</td></tr><tr><td>控制资源世界压力</td><td>提高 <code>cooldown.seconds</code>，必要时只给特定组 <code>yurtp.use</code>。</td></tr><tr><td>允许工作人员救援玩家</td><td>给工作人员 <code>yurtp.teleport.others</code>，但不一定给 <code>yurtp.reload</code>。</td></tr><tr><td>经济服保持金币消耗</td><td>不要给普通玩家或普通 VIP <code>yurtp.bypass.cost</code>。</td></tr><tr><td>活动世界快速分发玩家</td><td>给活动管理员 <code>yurtp.teleport.others</code> 与 <code>yurtp.bypass.wait</code>。</td></tr></tbody></table>`,21)])])}const b=e(o,[["render",p]]);export{h as __pageData,b as default};
